def merge_intervals(intervals):
    if not intervals:
        return []
    result = [intervals[0]]
    for interval in intervals[1:]:
        start, end = interval
        if result[-1][1] < start:
            result.append([start, end])
        else:
            result[-1] = [start, end]
    return result
