def encode_runs(text):
    result = []
    runs = []
    current_char = None
    current_length = 0

    for char, run_length in text:
        if char is None:
            current_char = run_length
            current_length = run_length
        else:
            current_char = char
            current_length += run_length

        if current_length > 1:
            runs.append(f"{run_length}{char}")
        else:
            runs.append(char)

    return ''.join(runs)
